		const machine = new DatePickerStateMachine({
			mode: datePickerType,
			value,
			minDate: parseDateToPlainDate(minDate),
			maxDate: parseDateToPlainDate(maxDate),
			dateFormat,
			isDisabled: disabled,
			isReadonly: readOnly
