		const newMaxDate = parseDateToPlainDate(maxDate);
		if (newMinDate) machine.send(DatePickerEvent.SET_MIN_DATE, { date: newMinDate });
		if (newMaxDate) machine.send(DatePickerEvent.SET_MAX_DATE, { date: newMaxDate });
